import sys
from pathlib import Path
import shutil
import subprocess

# Check for --ci flag
ci_mode = "--ci" in sys.argv
profile = "conan/rpi.ci.profile" if ci_mode else "conan/rpi.profile"

if Path("build").exists():
    shutil.rmtree("build")

subprocess.run([
   "conan", "export", "conan/pigpio", "--name=pigpio", "--version=79"
], check=True)

# Run conan install with selected profile
subprocess.run([
    "conan", "install", ".", f"--profile={profile}", "--output-folder=build", "--build=missing"
], check=True)

# Use CMake preset generated by Conan for cross-compilation
subprocess.run([
    "cmake", "--preset", "conan-release"
], check=True)
subprocess.run([
    "cmake", "--build", "--preset", "conan-release"
], check=True)